                        continue
                    stack = [(r, c)]
                    seen.add((r, c))
                    size = 0
                    while stack:
                        y, x = stack.pop()
                        size += 1
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = y + dy, x + dx
                            if (0 <= ny < 7 and 0 <= nx < 7
                                    and (ny, nx) not in seen
                                    and patch[ny][nx] == color):
                                seen.add((ny, nx))
                                stack.append((ny, nx))
                    largest[color] = max(largest.get(color, 0), size)
                    counts[color] = counts.get(color, 0) + size

            if not largest:
                row_out.append(0)
            else:
                row_out.append(max(largest, key=lambda color: (largest[color], counts[color])))
        out.append(row_out)
